package hu.synostream.android;
import java.util.*;import org.json.*;import org.junit.Test;import static org.junit.Assert.*;
public class Review1128Test {
 @Test public void sampleRequiresRelativeEvidence(){assertFalse(MediaLogic.sample("Sample Show - 01.mkv",120000000L,125000000L));assertTrue(MediaLogic.sample("Sample-Movie.mkv",50000000L,4000000000L));assertFalse(MediaLogic.sample("Sample-Movie.mkv",3000000000L,4000000000L));assertFalse(MediaLogic.sample("Sample-Movie.mkv",100,-1));assertFalse(MediaLogic.sample("Sample-Movie.mkv",-1,4000000000L));assertTrue(MediaLogic.sample("Movie.sample.mkv"));}
 @Test public void barePrivatePortsChooseCorrectProtocol(){String[][] cases={{"192.168.1.2","http://192.168.1.2:5000"},{"nas.local","http://nas.local:5000"},{"nas.local:5001","https://nas.local:5001"},{"192.168.1.2:5001","https://192.168.1.2:5001"},{"192.168.1.2:443","https://192.168.1.2:443"},{"192.168.1.2:5000","http://192.168.1.2:5000"},{"192.168.1.2:80","http://192.168.1.2:80"},{"192.168.1.2:5555","https://192.168.1.2:5555"},{"http://192.168.1.2:5001","http://192.168.1.2:5001"},{"https://192.168.1.2:5000","https://192.168.1.2:5000"}};for(String[] c:cases)assertEquals(c[0],c[1],NasRoutes.plan(new NasClient.Credentials(c[0],"","","","fixture","fixture",""),true).get(0).value);}
 @Test public void sampleTitleRemainsInDeletionAndTorrentSelection()throws Exception{String folder=MediaDeletionTest.ROOT+"/Sample Show",a=folder+"/Sample Show - 01.mkv",b=folder+"/Sample Show - 02.mkv";MediaDeletionTest.Files fs=new MediaDeletionTest.Files(a,b);for(String path:List.of(a,b)){NasClient.Entry old=fs.rows.get(path),entry=new NasClient.Entry(old.name,path,false,path.equals(a)?120000000L:125000000L);entry.realPath=old.realPath;fs.rows.put(path,entry);}MediaDeletion inv=new MediaDeletion(List.of(folder),List.of(MediaDeletionTest.ROOT),false,fs,List.of());assertEquals(Set.of(a,b),new HashSet<>(inv.plan(Set.of(1)).files));JSONArray files=new JSONArray().put(new JSONObject().put("name",a).put("size",120000000L)).put(new JSONObject().put("name",b).put("size",125000000L));Map<String,Long> sizes=DownloadStation.torrentVideoSizes(files);assertTrue(DownloadStation.defaultSelected(files.getJSONObject(0),"",sizes));assertTrue(DownloadStation.defaultSelected(files.getJSONObject(1),"",sizes));}
 @Test public void smallSampleTitleRemainsInLibrary()throws Exception{List<NasClient.Entry> rows=List.of(new NasClient.Entry("Sample Size.mkv","/movies/Sample Size.mkv",false,100000000L));Library.Source source=new Library.Source(){public List<NasClient.Entry> list(String path){return rows;}public byte[] readFile(String path,int limit)throws Exception{throw new java.io.IOException("No NFO in fixture");}};Library library=new Library(source,(endpoint,params)->new JSONObject().put("results",new JSONArray()));assertEquals(1,library.scan("/movies",true,n->{}).size());}
}
